#include <iostream>
#include <vector>
#include <string>
using namespace std;

int valueOf(char c) {
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        default: return 1000;
    }
}

int main() {
    string s;
    cin >> s;

    int total = 0;
    for (size_t i = 0; i < s.size(); i++) {
        int v = valueOf(s[i]);
        if (i + 1 < s.size() && v < valueOf(s[i + 1])) total -= v;
        else total += v;
    }
    cout << total << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    static int valueOf(char c) {
        switch (c) {
            case 'I': return 1;
            case 'V': return 5;
            case 'X': return 10;
            case 'L': return 50;
            case 'C': return 100;
            default: return c == 'D' ? 500 : 1000;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int v = valueOf(s.charAt(i));
            if (i + 1 < s.length() && v < valueOf(s.charAt(i + 1))) total -= v;
            else total += v;
        }
        System.out.println(total);
    }
}
